package com.backend.nutri_predic.actividadfisica.service;
import com.backend.nutri_predic.actividadfisica.dto.*; import com.backend.nutri_predic.actividadfisica.entity.*; import com.backend.nutri_predic.actividadfisica.repository.*; import com.backend.nutri_predic.common.service.AccessService; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EvaluacionActividadFisicaService { private final EvaluacionActividadFisicaRepository repo; private final AccessService access; public EvaluacionActividadFisicaService(EvaluacionActividadFisicaRepository repo,AccessService access){this.repo=repo;this.access=access;}
 @Transactional public EvaluacionActividadFisicaResponse registrar(Long clienteId,EvaluacionActividadFisicaRequest r,Authentication a){var c=access.client(clienteId,a); if(r.vigenciaDesde()!=null&&r.vigenciaHasta()!=null&&r.vigenciaDesde().isAfter(r.vigenciaHasta()))throw new IllegalArgumentException("Vigencia inválida"); var x=new EvaluacionActividadFisica();x.setCliente(c);x.setFechaEvaluacion(r.fechaEvaluacion());x.setInstrumentoCodigo(r.instrumentoCodigo().trim());x.setInstrumentoVersion(r.instrumentoVersion().trim());x.setNivelResultado(r.nivelResultado().trim());x.setValorResultado(r.valorResultado());x.setFuenteReferencia(r.fuenteReferencia().trim());x.setValidada(r.validada());x.setVigenciaDesde(r.vigenciaDesde());x.setVigenciaHasta(r.vigenciaHasta());return EvaluacionActividadFisicaResponse.from(repo.save(x));}
 @Transactional(readOnly=true) public List<EvaluacionActividadFisicaResponse> listar(Long clienteId,Authentication a){access.client(clienteId,a);return repo.findByClienteIdOrderByFechaEvaluacionDesc(clienteId).stream().map(EvaluacionActividadFisicaResponse::from).toList();}}
